#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps the tracker reachable for GC; a raw pointer was purged ~60 s in (shipping log, LogGarbage then AddPoints AV).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker was a raw UArenaScoreTracker* without UPROPERTY, so the garbage collector did not see the reference and purged the object about a minute into play (LogGarbage at 21.05.13); the next goal called AddPoints on the dangling pointer and hit EXCEPTION_ACCESS_VIOLATION (ArenaScoreTracker.cpp:18 from ArenaGameMode.cpp:38). Fixed by making it a UPROPERTY() TObjectPtr.",
  "no_colors_cause": "The palette data asset /Game/Data/Palettes/DA_Primary is only referenced by a string path in LoadObject, so the cooker did not include it (bCookAll=False, only /Game/Data/Effects in DirectoriesToAlwaysCook). In the packaged build the load fails, Palette is null and the HUD falls back to gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook in Config/DefaultGame.ini."
}
